# Election setup for corla-observer: the 2026 general election (3 November 2026).
# Edit it in place; the next crawl records the new version in the event log.
format = 1
election = "2026/general"
title = "2026 General Election"
audit_center = "https://www.coloradosos.gov/pubs/elections/auditCenter.html"
pilot_counties = ["La Plata", "Weld", "Morgan"]

# Fetched on every crawl even before the Audit Center page links them: the
# 2026 primary's file names with "primary" replaced by "general". A file not
# there yet is recorded once as missing. Add or correct addresses here.
probe_urls = [
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/riskLimit.html",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/files/targetContestSelections.xlsx",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/countyManifest.html",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/files/uploadStatus.csv",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/finalReports/ContestsListRound1.csv",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/finalReports/ContestMarginAndContestCVR-IDs-Round1.csv",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/finalReports/ContestIDsByCounty.csv",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/finalReports/CountyBallotManifestToCVRcomparison.csv",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/finalReports/CanonicalListOfContestsAndChoices.csv",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/finalReports/CandidateVoteTotalsSummary.csv",
  "https://www.coloradosos.gov/pubs/elections/RLA/2026/general/finalReports/CandidateVoteTotalsByCounty.csv",
